const fs = require('fs');
const path = require('path');
const pagesDir = path.join($json.tender_root, '02_Parsed_Text', 'pages');
const files = fs.existsSync(pagesDir) ? fs.readdirSync(pagesDir).filter(f => f.endsWith('.txt')) : [];
return files.map(f => ({json: {...$json, page_file: f, page_text: fs.readFileSync(path.join(pagesDir, f), 'utf-8').slice(0, 12000)}}));

const fs = require('fs');
const path = require('path');
const outDir = path.join($json.tender_root, '06_Scope_Extract');
fs.mkdirSync(outDir, { recursive: true });
const raw = Array.isArray($json.items) ? $json.items : [];
const rows = [];
for (const r of raw) { try { const t = r.output_text || r.output?.[0]?.content?.[0]?.text || '{}'; const obj = JSON.parse(t); for (const it of (obj.items || [])) rows.push(it); } catch {} }
const unique = []; const seen = new Set();
for (const it of rows) { const key = `${it.trade}|${it.description}|${it.uom}`; if (seen.has(key)) continue; seen.add(key); unique.push(it); }
fs.writeFileSync(path.join(outDir, 'scope_extract.json'), JSON.stringify(unique, null, 2));
const esc = (v) => String(v ?? '').replace(/,/g, ';').replace(/\n/g, ' ');
const csv = ['Trade,Description,Qty,UoM,Evidence_File,Evidence_Page,Evidence_Snippet,Confidence'];
for (const i of unique) { const e = i.evidence || {}; csv.push(`${esc(i.trade)},${esc(i.description)},${i.qty ?? ''},${esc(i.uom)},${esc(e.file)},${e.page||''},${esc(e.snippet)},${esc(i.confidence)}`); }
fs.writeFileSync(path.join(outDir, 'scope_extract.csv'), csv.join('\n'));
return [{json: {...$json, scope_items: unique}}];
